<span class="line">		cmds<span class="token punctuation">.</span>deleteUI<span class="token punctuation">(</span><span class="token string">&quot;EzRenameWin&quot;</span><span class="token punctuation">,</span> window<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span></span>
